7	/**
8	 * @fileoverview Manages browser lifecycle for the Browser Agent.
9	 *
10	 * Handles:
11	 * - Browser management via chrome-devtools-mcp with --isolated mode
12	 * - CDP connection via raw MCP SDK Client (NOT registered in main registry)
13	 * - Visual tools via --experimental-vision flag
14	 *
15	 * IMPORTANT: The MCP client here is ISOLATED from the main agent's tool registry.
16	 * Tools discovered from chrome-devtools-mcp are NOT registered in the main registry.
17	 * They are wrapped as DeclarativeTools and passed directly to the browser agent.
18	 */
19	
20	import { Client } from '@modelcontextprotocol/sdk/client/index.js';
21	import { StdioClientTransport } from '@modelcontextprotocol/sdk/client/stdio.js';
22	import type { Tool as McpTool } from '@modelcontextprotocol/sdk/types.js';
23	import { debugLogger } from '../../utils/debugLogger.js';
24	import type { Config } from '../../config/config.js';
25	import { Storage } from '../../config/storage.js';
26	import { injectInputBlocker } from './inputBlocker.js';
27	import * as path from 'node:path';
28	import * as fs from 'node:fs';
29	import { fileURLToPath } from 'node:url';
30	import { injectAutomationOverlay } from './automationOverlay.js';
31	
32	const __filename = fileURLToPath(import.meta.url);
33	const __dirname = path.dirname(__filename);
34	
35	// Default browser profile directory name within ~/.gemini/
36	const BROWSER_PROFILE_DIR = 'cli-browser-profile';
37	
38	// Default timeout for MCP operations
39	const MCP_TIMEOUT_MS = 60_000;
40	
41	/**
42	 * Tools that can cause a full-page navigation (explicitly or implicitly).
43	 *
44	 * When any of these completes successfully, the current page DOM is replaced
45	 * and the injected automation overlay is lost. BrowserManager re-injects the
46	 * overlay after every successful call to one of these tools.
47	 *
48	 * Note: chrome-devtools-mcp is a pure request/response server and emits no
49	 * MCP notifications, so listening for page-load events via the protocol is
50	 * not possible. Intercepting at callTool() is the equivalent mechanism.
51	 */
52	const POTENTIALLY_NAVIGATING_TOOLS = new Set([
53	  'click', // clicking a link navigates
54	  'click_at', // coordinate click can also follow a link
55	  'navigate_page',
56	  'new_page',
57	  'select_page', // switching pages can lose the overlay
58	  'press_key', // Enter on a focused link/form triggers navigation
59	  'handle_dialog', // confirming beforeunload can trigger navigation
60	]);
61	
62	/**
63	 * Content item from an MCP tool call response.
64	 * Can be text or image (for take_screenshot).
65	 */
66	export interface McpContentItem {
67	  type: 'text' | 'image';
68	  text?: string;
69	  /** Base64-encoded image data (for type='image') */
70	  data?: string;
71	  /** MIME type of the image (e.g., 'image/png') */
72	  mimeType?: string;
73	}
74	
75	/**
76	 * Result from an MCP tool call.
77	 */
78	export interface McpToolCallResult {
79	  content?: McpContentItem[];
80	  isError?: boolean;
81	}
82	
83	/**
84	 * Manages browser lifecycle and ISOLATED MCP client for the Browser Agent.
85	 *
86	 * The browser is launched and managed by chrome-devtools-mcp in --isolated mode.
87	 * Visual tools (click_at, etc.) are enabled via --experimental-vision flag.
88	 *
89	 * Key isolation property: The MCP client here does NOT register tools
90	 * in the main ToolRegistry. Tools are kept local to the browser agent.
91	 */
92	export class BrowserManager {
93	  // Raw MCP SDK Client - NOT the wrapper McpClient
94	  private rawMcpClient: Client | undefined;
95	  private mcpTransport: StdioClientTransport | undefined;
96	  private discoveredTools: McpTool[] = [];
97	
98	  /**
99	   * Whether to inject the automation overlay.
100	   * Always false in headless mode (no visible window to decorate).
101	   */
102	  private readonly shouldInjectOverlay: boolean;
103	  private readonly shouldDisableInput: boolean;
104	
105	  constructor(private config: Config) {
106	    const browserConfig = config.getBrowserAgentConfig();
107	    this.shouldInjectOverlay = !browserConfig?.customConfig?.headless;
108	    this.shouldDisableInput = config.shouldDisableBrowserUserInput();
109	  }
110	
111	  /**
112	   * Gets the raw MCP SDK Client for direct tool calls.
113	   * This client is ISOLATED from the main tool registry.
114	   */
115	  async getRawMcpClient(): Promise<Client> {
116	    if (this.rawMcpClient) {
117	      return this.rawMcpClient;
118	    }
119	    await this.ensureConnection();
120	    if (!this.rawMcpClient) {
121	      throw new Error('Failed to initialize chrome-devtools MCP client');
122	    }
123	    return this.rawMcpClient;
124	  }
125	
126	  /**
127	   * Gets the tool definitions discovered from the MCP server.
128	   * These are dynamically fetched from chrome-devtools-mcp.
129	   */
130	  async getDiscoveredTools(): Promise<McpTool[]> {
131	    await this.ensureConnection();
132	    return this.discoveredTools;
133	  }
134	
135	  /**
136	   * Calls a tool on the MCP server.
137	   *
138	   * @param toolName The name of the tool to call
139	   * @param args Arguments to pass to the tool
140	   * @param signal Optional AbortSignal to cancel the call
141	   * @returns The result from the MCP server
142	   */
143	  async callTool(
144	    toolName: string,
145	    args: Record<string, unknown>,
146	    signal?: AbortSignal,
147	  ): Promise<McpToolCallResult> {
148	    if (signal?.aborted) {
149	      throw signal.reason ?? new Error('Operation cancelled');
150	    }
151	
152	    const errorMessage = this.checkNavigationRestrictions(toolName, args);
153	    if (errorMessage) {
154	      return {
155	        content: [
156	          {
157	            type: 'text',
158	            text: errorMessage,
159	          },
160	        ],
161	        isError: true,
162	      };
163	    }
164	
165	    const client = await this.getRawMcpClient();
166	    const callPromise = client.callTool(
167	      { name: toolName, arguments: args },
168	      undefined,
169	      { timeout: MCP_TIMEOUT_MS },
170	    );
171	
172	    let result: McpToolCallResult;
173	
174	    // If no signal, just await directly
175	    if (!signal) {
176	      result = this.toResult(await callPromise);
177	    } else {
178	      // Race the call against the abort signal
179	      let onAbort: (() => void) | undefined;
180	      try {
181	        const raw = await Promise.race([
182	          callPromise,
183	          new Promise<never>((_resolve, reject) => {
184	            onAbort = () =>
185	              reject(signal.reason ?? new Error('Operation cancelled'));
186	            signal.addEventListener('abort', onAbort, { once: true });
187	          }),
188	        ]);
189	        result = this.toResult(raw);
190	      } finally {
191	        if (onAbort) {
192	          signal.removeEventListener('abort', onAbort);
193	        }
194	      }
195	    }
196	
197	    // Re-inject the automation overlay and input blocker after tools that
198	    // can cause a full-page navigation. chrome-devtools-mcp emits no MCP
199	    // notifications, so callTool() is the only interception point.
200	    if (
201	      !result.isError &&
202	      POTENTIALLY_NAVIGATING_TOOLS.has(toolName) &&
203	      !signal?.aborted
204	    ) {
205	      try {
206	        if (this.shouldInjectOverlay) {
207	          await injectAutomationOverlay(this, signal);
208	        }
209	        // Only re-inject the input blocker for tools that *reliably*
210	        // replace the page DOM (navigate_page, new_page, select_page).
211	        // click/click_at are handled by pointer-events suspend/resume
212	        // in mcpToolWrapper — no full re-inject roundtrip needed.
