18	  const finalPrompt =
19	    (prompt ? prompt + ' ' : '') +
20	    'Opening authentication page in your browser. ';
21	
22	  if (isHeadlessMode()) {
23	    return getOauthConsentNonInteractive(finalPrompt);
24	  } else if (coreEvents.listenerCount(CoreEvent.ConsentRequest) > 0) {
25	    return getOauthConsentInteractive(finalPrompt);
26	  }
27	  throw new FatalAuthenticationError(
28	    'Authentication consent could not be obtained.
