import * as fs from 'node:fs';
import * as path from 'node:path';
import { CoreEvent, coreEvents } from './events.js';
import { Storage } from '../config/storage.js';

/** Filename of the sentinel recording that browser consent was acknowledged. */
const CONSENT_SENTINEL_FILENAME = 'browser-consent-acknowledged.txt';

/** Content written to the sentinel file once consent is acknowledged. */
const CONSENT_SENTINEL_CONTENT = 'consent acknowledged';

/**
 * The privacy notice shown to the user before the browser agent starts.
 */
const CONSENT_PROMPT =
  'Privacy Notice: The browser agent controls a Chrome browser to complete ' +
  'tasks on your behalf. Page content and other data may be collected and ' +
  'processed. By continuing you acknowledge this and Google’s Privacy ' +
  'Policy at https://policies.google.com/privacy.\n\n' +
  'Do you want to continue?';

/**
 * Path to the consent sentinel file within the global Gemini directory.
 */
function getConsentSentinelPath(): string {
  return path.join(Storage.getGlobalGeminiDir(), CONSENT_SENTINEL_FILENAME);
}

/**
 * Writes the consent sentinel file, recording that consent has been
 * acknowledged so future runs skip the prompt.
 */
function writeConsentSentinel(): void {
  const sentinelPath = getConsentSentinelPath();
  fs.mkdirSync(path.dirname(sentinelPath), { recursive: true });
  fs.writeFileSync(sentinelPath, CONSENT_SENTINEL_CONTENT);
}

/**
 * Ensures the user has consented to the browser agent's data-collection
 * practices before the browser starts.
 *
 * - If consent was previously acknowledged (sentinel file exists), returns
 *   `true` immediately.
 * - In non-interactive mode (no listeners on `coreEvents`), consent is
 *   auto-accepted: the sentinel is written and `true` is returned.
 * - In interactive mode, a consent request is emitted. Returns `true` if the
 *   user accepts (writing the sentinel), or `false` if the user declines.
 */
export async function getBrowserConsentIfNeeded(): Promise<boolean> {
  if (fs.existsSync(getConsentSentinelPath())) {
    return true;
  }

  // Non-interactive mode: no UI is listening for consent requests, so
  // auto-accept and persist the acknowledgement.
  if (coreEvents.listenerCount(CoreEvent.ConsentRequest) === 0) {
    writeConsentSentinel();
    return true;
  }

  // Interactive mode: ask the user and wait for their decision.
  return new Promise<boolean>((resolve) => {
    coreEvents.emitConsentRequest({
      prompt: CONSENT_PROMPT,
      onConfirm: (confirmed: boolean) => {
        if (confirmed) {
          writeConsentSentinel();
        }
        resolve(confirmed);
      },
    });
  });
}
